int totalLen(node* p, int len, int& sum) {//返回值是结点总数，len是当前结点的路径长度，sum是这棵树路径长度之和
    if (!p)return 0;
    sum += len;
    return 1 + totalLen(p->left, len + 1, sum) + totalLen(p->left, len + 1, sum);
}

double ASL(node* p) {
    int sum = 0;
    int nodeNum = totalLen(p, 1, sum);
    return sum / (double)nodeNum;
}
