【代码实现（C/C++）】
```c
bool Del_Min(LinkList &L) {
    if (L == NULL || L->next == NULL)     /* 边界：头指针无效或为空表 */
        return false;
    LNode *pre = L, *p = L->next;         /* p 为工作指针，pre 为 p 的前驱 */
    LNode *minpre = pre, *minp = p;       /* 记录当前最小值结点及其前驱 */
    while (p != NULL) {
        if (p->data < minp->data) {       /* 发现更小值，更新最小值及前驱指针 */
            minp = p;
            minpre = pre;
        }
        pre = p;                          /* 同步后移一组指针 */
        p = p->next;
    }
    minpre->next = minp->next;            /* 从链表上摘下最小值结点 */
    free(minp);                           /* 释放被删结点空间 */
    return true;
}
```

【代码实现（C/C++）】
```c
void Reverse(LinkList &L) {
    if (L == NULL || L->next == NULL)  /* 边界：空表或仅含一个结点无需逆置 */
        return;
    LNode *p = L->next, *r;            /* p 指向原表首元结点 */
    L->next = NULL;                    /* 置空头结点后继，准备头插重建 */
    while (p != NULL) {
        r = p->next;                   /* 1. 暂存后继结点，防止断链 */
        p->next = L->next;             /* 2. 将 p 插在 L 之后（新表最前端） */
        L->next = p;                   /* 3. 更新首元指针 */
        p = r;                         /* 4. 推进到原链表的下一个结点 */
    }
}
```

