【代码实现（C/C++）】
```c
Status ListInsert_WithHeadNode(LinkList &L, ElemType e)
{   /* L 带头结点，元素按 data 非递减有序 */
    if (L == NULL) return ERROR;          /* 防御：头结点指针非法 */
    LinkList P = L->next;                 /* P 指向当前考察结点 */
    LinkList Q = L;                       /* Q 始终为 P 的直接前驱，初值为头结点 L */
    LinkList S;
    while (P != NULL && P->data <= e) {   /* 遇到等值元素继续后移，保证相同元素后插（稳定性） */
        Q = P;
        P = P->next;
    }
    S = (LinkList)malloc(sizeof(LNode));  /* 仅申请一个新结点 */
    if (S == NULL) return ERROR;          /* 内存分配失败检查 */
    S->data = e;
    S->next = P;                          /* 先接后继 P，不断链 */
    Q->next = S;                          /* 再将 S 挂到前驱 Q 之后 */
    return OK;
}
```

